export type FeatureScreenKind =
  | 'briefing-radio' | 'memory' | 'routines' | 'voice-meetings'
  | 'workboard' | 'knowledge' | 'creation' | 'ecosystem'
  | 'appearance' | 'notifications' | 'administration' | 'mobile';

export type FeatureScreenDetail =
  | 'today' | 'radio' | 'health' | 'memories' | 'relations' | 'psyche'
  | 'personality' | 'journals' | 'scheduled' | 'conditional' | 'heartbeat'
  | 'habits' | 'meeting' | 'transcript' | 'live' | 'voice' | 'phone' | 'simli'
  | 'board' | 'ticket' | 'space' | 'attachments' | 'files' | 'images'
  | 'diagram' | 'connectors' | 'skills' | 'mcp' | 'plugins' | 'peers'
  | 'costs' | 'preferences' | 'subagents' | 'relations-central'
  | 'display-cards' | 'display-html' | 'reminder' | 'planning' | 'registry'
  | 'users' | 'llm-pricing' | 'llm-config' | 'platform-health'
  | 'pwa-mobile' | 'pwa-install';

export interface FeatureScreenFocus {
  x: number; y: number; width: number; height: number; title?: string;
}

export interface FeatureScreenEvidence {
  title: string;
  route: string;
  sourceComponents: readonly string[];
  referenceAssets: readonly string[];
  featureKeys: readonly string[];
  /** A settings screen proves the controls, not an executed provider result. */
  proof: 'native-demo-ui' | 'source-ui-demo' | 'configuration';
  providerExecution: false;
  mutatesAccount: false;
  limitations: readonly string[];
}

