const evidence = (title: string, route: string, sources: string[], assets: string[], keys: string[], proof: FeatureScreenEvidence['proof'] = 'native-demo-ui', limitations: string[] = []): FeatureScreenEvidence => ({
  title, route, sourceComponents: sources, referenceAssets: assets.map(reference), featureKeys: keys,
  proof, providerExecution:false, mutatesAccount:false, limitations: [demoLimit, ...limitations],
});

