/** V5 screens are projections of the named native components, using only
 * controlled fixtures. Their frame changes illustrate UI states, not calls. */
function DisplayView({ html = false }: { html?: boolean }) {
  const choices: [Icon,string][] = [[LayoutGrid,'Cartes HTML'],[FileText,'HTML enrichi'],[PanelsTopLeft,'HTML enrichi + cartes'],[Type,'Markdown']];
  return <SettingsShell active="Mode d’affichage"><Section title="Mode d’affichage" description="Choisir le format de rendu des réponses" I={LayoutGrid}>
    <div className="fs-display-modes">{choices.map(([I,label],index)=><button type="button" key={label} aria-pressed={index===(html?1:0)} className={cx('fs-display-mode',index===(html?1:0)&&'is-selected')}>{icon(I,20)}<span>{label}</span></button>)}</div>
    <small>{html?'Réponses mises en page : titres, encadrés, badges, sections dépliables, tableaux, colonnes, chiffres clés et code coloré':'Fiches visuelles structurées pour les données (contacts, événements, emails, météo, etc.)'}</small>
    <div className="fs-info-note">{icon(Info)}<p>Choisis les cartes de données, la mise en page enrichie, les deux ensemble, ou le format Markdown.</p></div>
  </Section></SettingsShell>;
}

