export const REMINDER_DEMO_TRIGGER_SECONDS = 2.6;
export const REMINDER_PENDING_FOCUS = f(112,499,1216,148,'Rappel à venir');
export const REMINDER_TOAST_FOCUS = f(545,32,350,104,'Notification reçue');

export function getReminderPresentation(seconds: number) {
  const fired=seconds>=REMINDER_DEMO_TRIGGER_SECONDS;
  const toastOpacity=Math.min(1,Math.max(0,(seconds-REMINDER_DEMO_TRIGGER_SECONDS)/.22));
  return { fired,toastOpacity,focus:fired?REMINDER_TOAST_FOCUS:REMINDER_PENDING_FOCUS };
}

/** The same Sonner info notification in the native screen and detached film
 * object. The film may move it, but its text and controls have one rendering. */
export function NativeReminderToast({opacity=1,detached=false}: {opacity?:number;detached?:boolean}) {
  return <div className="fs-reminder-toast" role="status" style={{opacity,...(detached?{position:'relative',left:0,top:0}:{})}}>{icon(Info,20)}<p>C’est le moment d’appeler Morgan Démo pour confirmer la date du fournisseur.</p><button type="button" aria-label="Fermer">{icon(X,16)}</button></div>;
}

