/** An offline projection of the real frontend. Camera/crop choreography is
 * owned by the film, while these components keep the native UI hierarchy.
 * The only automatic changes are presentation states (fold/playback), never
 * a real provider request, saved preference, message or executed action. */
export function FeatureScreen({ kind, frame, fps, detail = FEATURE_SCREEN_DEFAULTS[kind], withBackdrop = true,reminderToastOpacity }: FeatureScreenProps) {
  if (!FEATURE_SCREEN_METADATA[kind][detail]) throw new Error(`Unsupported native screen: ${kind}/${detail}`);
  const seconds = frame/fps;
  let content: ReactNode;
  switch(detail) {
    case 'today': content=<TodayView/>; break;
    case 'radio': content=<RadioView seconds={seconds}/>; break;
    case 'memories': content=<MemoryView seconds={seconds}/>; break;
    case 'relations': content=<RelationsView/>; break;
    case 'relations-central': content=<RelationCentralView/>; break;
    case 'psyche': content=<PsycheView/>; break;
    case 'personality': content=<PersonalityView/>; break;
    case 'journals': content=<JournalsView/>; break;
    case 'health': content=<HealthView/>; break;
    case 'scheduled': content=<RoutineView/>; break;
    case 'conditional': content=<ConditionalView/>; break;
    case 'heartbeat': content=<HeartbeatView/>; break;
    case 'habits': content=<HabitsView/>; break;
    case 'meeting': content=<MeetingView/>; break;
    case 'transcript': content=<MeetingView transcript/>; break;
    case 'live': content=<LiveView/>; break;
    case 'voice': content=<VoiceView/>; break;
    case 'simli': content=<SimliView/>; break;
    case 'phone': content=<PhoneView/>; break;
    case 'board': content=<WorkboardView/>; break;
    case 'ticket': content=<WorkboardView detail/>; break;
    case 'space': case 'attachments': content=<KnowledgeView/>; break;
    case 'files': content=<FilesView/>; break;
    case 'images': content=<ImagesView/>; break;
    case 'diagram': content=<McpView diagram/>; break;
    case 'connectors': content=<ConnectorsView/>; break;
    case 'skills': content=<SkillsView/>; break;
    case 'mcp': content=<McpView/>; break;
    case 'plugins': content=<PluginsView/>; break;
    case 'peers': content=<PeersView/>; break;
    case 'costs': content=<CostsView/>; break;
    case 'preferences': content=<PreferencesView/>; break;
    case 'subagents': content=<SubagentsView/>; break;
    case 'display-cards': content=<DisplayView/>; break;
    case 'display-html': content=<DisplayView html/>; break;
    case 'reminder': content=<NotificationView seconds={seconds} reminderToastOpacity={reminderToastOpacity}/>; break;
    case 'planning': content=<PlanningView/>; break;
    case 'registry': content=<RegistryView/>; break;
    case 'users': content=<AdminUsersView/>; break;
    case 'llm-pricing': content=<LLMPricingView/>; break;
    case 'llm-config': content=<LLMConfigView seconds={seconds}/>; break;
    case 'platform-health': content=<PlatformHealthView/>; break;
    case 'pwa-mobile': case 'pwa-install': content=<div className="fs-mobile-source" style={{left:PWA_MOBILE_VIEWPORT.x,top:PWA_MOBILE_VIEWPORT.y}}><NativePwaMobile detail={detail}/></div>; break;
  }
  const nav=kind==='mobile'?'none':detail==='today'?'dashboard':['relations','relations-central'].includes(detail)?'relations':['meeting','transcript','board','ticket'].includes(detail)?'work':detail==='radio'?'radio':['space','attachments','registry','reminder'].includes(detail)?'none':'settings';
  return <div className="feature-screen product-story" data-detail={detail} data-nav={nav}>
    <style>{`@font-face{font-family:'Lia Story Inter';src:url('${staticFile('fonts/Inter-Variable.woff2')}') format('woff2');font-weight:100 900;font-display:block;}`}</style>
    {withBackdrop?<StoryLandingBackdrop width={1440} height={960} frame={frame} fps={fps}/>:null}
    {kind!=='mobile'?<NativeNavigation/>:null}
    <main>{content}</main>
  </div>;
}
